int main(void){em_cpu.rom=rom_data;em_cpu.rom_size=sizeof rom_data;em_cpu.audio_mode=AUDIO_ON;check(audio_init(&em_cpu,NULL),"real YMFM");em_host.dune_mouse.enabled=1;load("web/frontend.state.bin");wait_ready("main",30);for(unsigned i=0;i<3;i++){em_web_campaign_frontend_audio_request(&em_cpu,1);em_web_campaign.frontend_hold=1;cycle_route(2,i*2);check(at_route_poll[i*2]==0x418b8,"Tutorial readiness comes from actual script page poll");frames(30);check(em_web_campaign_input_request(&em_cpu,0,PAD_A),"original Tutorial page tap");uint64_t end=em_cpu.vdp.frames+200;while(em_web_campaign.input_pending&&em_cpu.vdp.frames<end)cycle_step();check(!em_web_campaign.input_pending,"Tutorial page tap consumed");cycle_route(0,i*2+1);check(at_route_poll[i*2+1]==0x178d2,"Main readiness comes from original complete planet/menu poll");check(em_web_campaign_house(&em_cpu)==-1&&!em_web_campaign.armed&&!em_web_campaign.outcome_seq,"tutorial cycles do not create world/progress");}puts("PASS repeated native Tutorial/Main3cycles, actual destination polls, no stale scene/planet readiness");fflush(stdout);
 campaign_case: memset(trace_sound_id,0,sizeof trace_sound_id);memset(scripted_sound,0,sizeof scripted_sound);check(em_web_campaign_sound_request(&em_cpu),"queued frontend click before campaign request");check(em_web_campaign_request(&em_cpu,requested_h,requested_m),"ordinary native campaign request");check(!em_web_campaign.sound_pending,"launch removes unconsumed duplicate host feedback");uint64_t end=em_cpu.vdp.frames+6000;while(em_web_campaign.stage!=4&&em_cpu.vdp.frames<end)cycle_step();check(em_web_campaign.stage==4,"original Atreides1 initialization reached manual briefing");unsigned menu_cues=scripted_sound[11]+scripted_sound[12]+scripted_sound[25]+scripted_sound[40];check(menu_cues==1,"hidden native menu navigation retains one actual confirm");check(em_web_campaign.campaign_feedback_suppressed>0,"only scripted native feedback was omitted");printf("PASS scripted campaign menu feedback: cue11=%u cue12=%u cue25=%u cue40=%u, suppressed=%llu, oneconfirm no extra host sound\n",scripted_sound[11],scripted_sound[12],scripted_sound[25],scripted_sound[40],(unsigned long long)em_web_campaign.campaign_feedback_suppressed);++campaign_cases;if(campaign_cases<6){static const int hh[5]={0,0,1,2,2},mm[5]={1,2,2,1,2};requested_h=hh[campaign_cases-1];requested_m=mm[campaign_cases-1];load("web/frontend.state.bin");wait_ready("main",30);goto campaign_case;}printf("PASS scripted native launch6cases allhouses/missions1and2; original initialization, oneconfirm, no false outcome\n");audio_finish(&em_cpu);return 0;}
